```ts
private getSlotConflicts(
  slot: Slot,
  slots: Slot[],
  blockingResourceIds: Set<number>,
): Slot[] {
  const slotStart = new Date(slot.start).getTime();
  const slotEnd = new Date(slot.end).getTime();

  return slots.filter((otherSlot) => {
    const otherStart = new Date(otherSlot.start).getTime();
    const otherEnd = new Date(otherSlot.end).getTime();

    const isRelevantResource =
      otherSlot.resourceId === slot.resourceId ||
      blockingResourceIds.has(otherSlot.resourceId);

    return (
      otherSlot.id !== slot.id &&
      isRelevantResource &&
      otherStart < slotEnd &&
      otherEnd > slotStart
    );
  });
}
```

This preserves the dependency direction: if Pool blocks Lane 1, Pool slots appear under Lane 1, but Lane 1 slots do not appear under Pool. It also ensures resources without their own slots are returned.

